import React, { useEffect, useRef, useState } from "react";
import { Html5Qrcode } from "html5-qrcode";

function QRScanner() {
  const scannerRef = useRef(null);
  const [student, setStudent] = useState(null);
  const [status, setStatus] = useState("");
  const [isScanning, setIsScanning] = useState(false);
  const isProcessing = useRef(false);

  useEffect(() => {
    // Initialize scanner instance once
    scannerRef.current = new Html5Qrcode("reader");

    return () => {
      // Cleanup: stop camera if user leaves page
      if (scannerRef.current && scannerRef.current.isScanning) {
        scannerRef.current.stop().catch((e) => console.log("Stop error", e));
      }
    };
  }, []);

  const startScanner = async () => {
    try {
      setStatus("");
      setStudent(null);
      
      await scannerRef.current.start(
        { facingMode: "environment" },
        {
          fps: 20,
          qrbox: { width: 250, height: 250 },
          aspectRatio: 1.0
        },
        onScanSuccess
      );
      setIsScanning(true);
    } catch (err) {
      console.error("Scanner failed:", err);
      alert("Camera Error: Please ensure you have allowed camera permissions.");
    }
  };

  const stopScanner = async () => {
    if (scannerRef.current && scannerRef.current.isScanning) {
      await scannerRef.current.stop();
      setIsScanning(false);
    }
  };

  const onScanSuccess = async (decodedText) => {
    if (isProcessing.current) return;
    isProcessing.current = true;

    try {
      const verify = await fetch(`http://localhost:5000/verify-user/${decodedText}`);
      const verifyData = await verify.json();

      if (!verifyData.success) {
        setStudent(null);
        setStatus("notfound");
      } else {
        setStudent(verifyData.user);
        const attendance = await fetch(
          `http://localhost:5000/mark-attendance/${decodedText}`,
          { method: "PUT" }
        );
        const attendanceData = await attendance.json();
        setStatus(attendanceData.success ? "success" : "already");
      }
    } catch (err) {
      setStatus("servererror");
    } finally {
      // 3-second cooldown to prevent double-scanning the same user
      setTimeout(() => { isProcessing.current = false; }, 3000);
    }
  };

  return (
    <div style={{ textAlign: "center", padding: "20px", fontFamily: "sans-serif" }}>
      <h2 style={{ color: "#333", marginBottom: "20px" }}>Admin Attendance Panel</h2>

      {/* Manual Control Buttons */}
      <div style={{ marginBottom: "20px" }}>
        {!isScanning ? (
          <button onClick={startScanner} style={btnStyle("#28a745")}>
            Open Camera
          </button>
        ) : (
          <button onClick={stopScanner} style={btnStyle("#dc3545")}>
            Close Camera
          </button>
        )}
      </div>

      {/* The Scanner Container */}
      <div style={{ position: "relative", maxWidth: "450px", margin: "auto" }}>
        <div
          id="reader"
          style={{
            width: "100%",
            minHeight: isScanning ? "300px" : "0px", 
            border: isScanning ? "5px solid #28a745" : "none",
            borderRadius: "15px",
            overflow: "hidden",
            backgroundColor: "#000",
            display: isScanning ? "block" : "none"
          }}
        ></div>

        {!isScanning && (
          <div style={placeholderStyle}>
            <p style={{ color: "#888" }}>Camera is Offline</p>
          </div>
        )}
      </div>

      {/* Data Result Display */}
      <div style={{ marginTop: "30px", minHeight: "160px" }}>
        {status === "notfound" && <h3 style={{ color: "red" }}>❌ Student Not Registered</h3>}
        {status === "servererror" && <h3 style={{ color: "red" }}>⚠️ Server connection failed</h3>}

        {student && (
          <div style={cardStyle}>
            <div style={{ borderBottom: "1px solid #eee", marginBottom: "10px" }}>
              <p style={{ fontSize: "12px", color: "#888", margin: "0" }}>VERIFIED STUDENT</p>
              <h2 style={{ margin: "5px 0", color: "#007bff" }}>{student.name}</h2>
            </div>
            
            <p style={{ fontSize: "16px", margin: "10px 0" }}>
              <strong>Event:</strong> {student.event_name || "General Admission"}
            </p>

            {status === "success" && (
              <div style={alertStyle("#d4edda", "#155724")}>✔ Attendance Marked Successfully</div>
            )}
            {status === "already" && (
              <div style={alertStyle("#fff3cd", "#856404")}>⚠️ Already Checked In</div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

// --- Styles ---
const btnStyle = (color) => ({
  padding: "12px 30px",
  backgroundColor: color,
  color: "white",
  border: "none",
  borderRadius: "8px",
  cursor: "pointer",
  fontSize: "16px",
  fontWeight: "bold"
});

const placeholderStyle = {
  width: "100%",
  height: "300px",
  backgroundColor: "#f9f9f9",
  border: "2px dashed #ccc",
  borderRadius: "15px",
  display: "flex",
  alignItems: "center",
  justifyContent: "center"
};

const cardStyle = {
  maxWidth: "400px",
  margin: "auto",
  padding: "20px",
  backgroundColor: "white",
  borderRadius: "15px",
  boxShadow: "0 4px 20px rgba(0,0,0,0.1)",
  textAlign: "left",
  borderLeft: "6px solid #007bff"
};

const alertStyle = (bg, color) => ({
  padding: "10px",
  backgroundColor: bg,
  color: color,
  borderRadius: "5px",
  fontWeight: "bold",
  textAlign: "center",
  marginTop: "10px"
});

export default QRScanner;
